<script lang="ts">
  import { controlTypes, controlCount, controlFacts, controlLocation, inventoryComplete, inventoryCount } from '../lib/control-inventory';
  import type { ControlSection } from '../lib/control-inventory';
  let { sections }: { sections: ControlSection[] } = $props();
  const complete = $derived(inventoryComplete(sections));
  const featured = controlTypes.filter(t => ['hat', 'analog_ministick', 'button', 'slider', 'encoder', 'scroll_wheel'].includes(t.type));
</script>

<section class="inventory" aria-label="Detailed physical control inventory">
  <header class="inventory-heading"><div><p class="eyebrow">KNOW EVERY INPUT</p><h2>Physical controls</h2><p class="intro">What you can reach. What you can press. Where it lives.</p></div><span class="coverage" class:complete>{complete ? 'Inventory checked' : 'Partial inventory'}</span></header>
  <div class="overview">{#each featured as family}<div><span class="symbol" aria-hidden="true">{family.icon}</span><strong>{inventoryCount(sections, family.type)}</strong><span>{family.label}</span></div>{/each}</div>
  <p class="legend">Counts describe physical controls, not software bindings. “Pressable” means a separate center click. Unknown means unconfirmed{complete ? '.' : '; an undocumented control is not necessarily absent.'}</p>
  {#each sections as section}
    <div class="component-section">
      <div class="component-heading"><h3>{section.name}</h3><span>{section.category.replaceAll('_', ' ')}</span></div>
      {#if section.controls.length}
        <div class="control-grid">{#each controlTypes as family}{@const entries = section.controls.filter(c => c.type === family.type)}{#if entries.length}
          <section class="family"><header><span class="family-icon" aria-hidden="true">{family.icon}</span><h4>{family.label}</h4><span class="family-count">{entries.reduce((n, c) => n + controlCount(c), 0)}</span></header>
            {#each entries as control}<div class="control"><div class="control-title"><strong>{controlCount(control)} × {control.label ?? family.label}</strong><span class="location">{controlLocation(control, section) === 'unknown' ? 'Location unknown' : controlLocation(control, section)}</span></div><dl>{#each controlFacts(control) as fact}<div><dt>{fact.label}</dt><dd class:unknown={fact.value === 'Unknown'} class:positive={fact.value === 'Yes'}>{fact.value}</dd></div>{/each}</dl>{#if control.notes}<p class="note">{control.notes}</p>{/if}{#if control.source}<a class="source" href={control.source} rel="external noopener">Control source ↗</a>{/if}</div>{/each}
          </section>
        {/if}{/each}</div>
      {:else}<p class="empty">No physical controls documented. Check the product source before assuming there are none.</p>{/if}
      {#if section.controls_evidence}<p class="evidence"><a href={section.controls_evidence.source} rel="external noopener">Inventory source ↗</a><span>Checked {section.controls_evidence.checked} · {section.controls_evidence.coverage} coverage</span></p>{#if section.controls_evidence.notes}<p class="note">{section.controls_evidence.notes}</p>{/if}{:else}<p class="evidence">This control breakdown has not yet been checked as a complete inventory.</p>{/if}
      <details class="missing"><summary>{section.controls_evidence?.coverage === 'complete' ? 'Control types absent from this inventory' : 'Control types still undocumented'}</summary><p>{controlTypes.filter(t => !section.controls.some(c => c.type === t.type)).map(t => t.label).join(' · ') || 'All control types have entries.'}</p></details>
    </div>
  {/each}
</section>

<style>
  .inventory{border:1px solid var(--border-cockpit);border-radius:8px;background:var(--bg-panel);padding:clamp(1rem,3vw,2rem);margin:0 0 2rem;min-width:0}.inventory-heading{display:flex;justify-content:space-between;align-items:flex-start;gap:1rem}.eyebrow{margin:0 0 .6rem;font:.65rem var(--font-mono);letter-spacing:.16em;color:var(--hud-cyan)}h2{margin:0;font-size:clamp(1.5rem,3vw,2rem);letter-spacing:-.035em}.intro{color:var(--text-secondary);font-size:.9rem;margin:.6rem 0 0}.coverage{border:1px solid var(--accent-amber);color:var(--accent-amber);border-radius:99px;padding:.4rem .65rem;font:.65rem var(--font-mono);white-space:nowrap}.coverage.complete{border-color:var(--hud-cyan);color:var(--hud-cyan)}.overview{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:1px;background:var(--border-cockpit);border:1px solid var(--border-cockpit);border-radius:5px;overflow:hidden;margin-top:1.6rem}.overview>div{background:var(--bg-cockpit);padding:1rem;display:grid;align-content:start;gap:.45rem}.symbol{color:var(--hud-cyan);font-size:1.3rem;line-height:1}.overview strong{font:clamp(.85rem,1.4vw,1.1rem) var(--font-mono);color:var(--text-primary);overflow-wrap:anywhere}.overview>div>span:last-child{font-size:.72rem;color:var(--text-secondary)}.legend{font-size:.75rem;color:var(--text-secondary);line-height:1.7;margin:1rem 0 1.8rem}.component-section+.component-section{border-top:1px solid var(--border-cockpit);padding-top:1.8rem;margin-top:1.8rem}.component-heading{display:flex;justify-content:space-between;gap:1rem;align-items:baseline;margin-bottom:1rem}.component-heading h3{margin:0;font-size:1rem;font-weight:500}.component-heading>span{color:var(--text-secondary);font:.65rem var(--font-mono);text-transform:uppercase}.control-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1rem}.family{border:1px solid var(--border-cockpit);border-radius:5px;overflow:hidden;align-self:start}.family>header{display:flex;align-items:center;gap:.65rem;padding:.8