  @media(max-width:1000px){.control-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.overview{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:600px){.inventory-heading{flex-direction:column}.control-grid{grid-template-columns:1fr}.overview>div{padding:.8rem .6rem}.component-heading{flex-direction:column;gap:.4rem}}
</style>
